// Generated by @canonical/summon-component:react v0.43.0

import { readFileSync } from "node:fs";
import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import SwatchMark from "./SwatchMark.js";

describe("SwatchMark SSR", () => {
  it("renders its colour inline on the server", () => {
    const html = renderToString(<SwatchMark colour="#e32017" />);
    expect(html).toContain('class="ds swatch-mark"');
    expect(html).toContain('aria-hidden="true"');
    expect(html).toContain("--swatch-mark-colour:#e32017");
  });

  it("names no colour of its own: the fill is the channel, the ring the muted text", () => {
    const styles = readFileSync(
      new URL("./styles.css", import.meta.url),
      "utf8",
    );
    expect(styles).toMatch(/background: var\(--swatch-mark-colour\);/);
    expect(styles).toMatch(
      /--swatch-mark-ring-color: var\(--color-text-muted\);/,
    );
    expect(styles).not.toMatch(/#[0-9a-f]{3,8}\b|rgb\(|hsl\(/i);
  });

  it("writes a plain colour from the data, a hex or a colour function", () => {
    expect(renderToString(<SwatchMark colour="#c8102e" />)).toContain(
      'style="--swatch-mark-colour:#c8102e"',
    );
    expect(
      renderToString(<SwatchMark colour="oklch(62% 0.21 25.3 / 0.9)" />),
    ).toContain('style="--swatch-mark-colour:oklch(62% 0.21 25.3 / 0.9)"');
  });

  it("writes no style for a colour that would add declarations, so it draws its ring alone", () => {
    for (const colour of [
      "red;position:fixed;inset:0;background:url(//host/x.png)",
      "url(//host/x.png)",
      "var(--x)",
    ]) {
      const html = renderToString(<SwatchMark colour={colour} />);
      expect(html).not.toContain("style=");
      expect(html).not.toContain("position");
      expect(html).not.toContain("url(");
    }
  });
});
